import type { DiscoverRequest, DiscoverResponse } from '@glia/api-client'
import { type UseQueryResult, useQuery } from '@tanstack/react-query'
import { useSessionStore } from '@/stores/session'

// Generous, and measured rather than picked: a cold `knowledge/search` against the live Cala
// API took 45.7s on 29 Aug 2026. This has to outlast the server's own read timeout, or the
// browser abandons a query we have already paid for and the user sees an error instead.
const REQUEST_TIMEOUT_MS = 120_000

function apiUrl(path: string): string {
  const base = import.meta.env.VITE_API_BASE_URL?.replace(/\/$/, '') ?? ''
  return `${base}${path}`
}

/**
 * A problem document carries a correlation id and nothing else worth showing. The upstream
 * detail stays on the server, so this is all the UI has to say — and all it should.
 */
export class DiscoveryError extends Error {
  constructor(readonly correlationId: string) {
    super('Discovery failed.')
    this.name = 'DiscoveryError'
  }
}

function correlationIdOf(body: unknown): string {
  if (typeof body === 'object' && body !== null && 'correlation_id' in body) {
    const value = (body as { correlation_id: unknown }).correlation_id
    if (typeof value === 'string') {
      return value
    }
  }
  return 'unknown'
}

async function discover(payload: DiscoverRequest): Promise<DiscoverResponse> {
  const response = await fetch(apiUrl('/v1/discover'), {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload),
    signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
  })
  const body: unknown = await response.json()
  if (!response.ok) {
    throw new DiscoveryError(correlationIdOf(body))
  }
  // The backend is the only shape authority here: these types are generated from its OpenAPI
  // schema by `pnpm gen:api`, so a drift is a build error rather than a runtime surprise.
  return body as DiscoverResponse
}

/**
 * Asks the backend what the speaker is talking about, once per turn the distiller lets through.
 *
 * The query key is `discoveryTranscript`, which the store only advances when the backend sends
 * `should_discover` — its own gate, evaluated on settled turns only, and true just when the
 * distilled attributes moved materially. That is the client half of the guard: an interim
 * delta never changes the key, and neither does a settled turn that said nothing new, so
 * neither can start a request. The server debounces, caches and meters independently — the
 * browser is not the thing holding the credit budget, and this guard exists to keep the
 * network quiet, not to be trusted with the money.
 */
export function useDiscovery(): UseQueryResult<DiscoverResponse, Error> {
  const sessionId = useSessionStore((state) => state.sessionId)
  const discoveryTranscript = useSessionStore((state) => state.discoveryTranscript)
  const enabled = Boolean(sessionId) && discoveryTranscript.trim().length > 0

  return useQuery({
    queryKey: ['discovery', sessionId, discoveryTranscript],
    enabled,
    // Nothing about a settled turn changes after the fact, so nothing should ever refetch it.
    staleTime: Number.POSITIVE_INFINITY,
    gcTime: 30 * 60_000,
    refetchOnWindowFocus: false,
    refetchOnReconnect: false,
    retry: false,
    queryFn: () => discover({ transcript: discoveryTranscript, session_id: sessionId ?? '' }),
  })
}

import asyncio
import hashlib
import logging
from collections.abc import Sequence
from typing import TYPE_CHECKING, Protocol

from glia.config import Settings
from glia.contracts import RealtimeTokenResponse

logger = logging.getLogger(__name__)

if TYPE_CHECKING:
    from openai import OpenAI


def _create_openai_client(
    *,
    api_key: str,
    timeout: float,
    max_retries: int,
    default_headers: dict[str, str],
) -> "OpenAI":
    # Import lazily so health checks and the deterministic websocket path do not
    # pay the SDK import cost. The key remains exclusively on the API process.
    from openai import OpenAI

    return OpenAI(
        api_key=api_key,
        timeout=timeout,
        max_retries=max_retries,
        default_headers=default_headers,
    )


class TokenBrokerUnavailable(RuntimeError):
    """Raised when live transcription has not been configured."""


class TokenMintFailed(RuntimeError):
    """Raised when OpenAI cannot mint a short-lived Realtime credential."""


class RealtimeTokenBroker(Protocol):
    async def mint(self, client_id: str, languages: Sequence[str]) -> RealtimeTokenResponse: ...


class OpenAIRealtimeTokenBroker:
    def __init__(self, settings: Settings) -> None:
        self._settings = settings

    async def mint(self, client_id: str, languages: Sequence[str]) -> RealtimeTokenResponse:
        api_key = self._settings.openai_api_key
        if api_key is None or not api_key.get_secret_value():
            raise TokenBrokerUnavailable("OPENAI_API_KEY is not configured")

        safety_identifier = hashlib.sha256(client_id.encode("utf-8")).hexdigest()

        def create_secret() -> RealtimeTokenResponse:
            client = _create_openai_client(
                api_key=api_key.get_secret_value(),
                timeout=self._settings.openai_request_timeout_seconds,
                max_retries=1,
                default_headers={"OpenAI-Safety-Identifier": safety_identifier},
